package com.enderkidleaf.tvinstaller;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class DeviceToolsActivity extends Activity {
    final ExecutorService worker=Executors.newSingleThreadExecutor();final List<View> buttons=new ArrayList<>();final List<App> apps=new ArrayList<>();
    AdbCore.Endpoint target;AdbCore.Keys keys;volatile AdbCore.Connection active;boolean busy,includeSystem;byte[] screenshot;Bitmap bitmap;
    TextView status;LinearLayout appRows;CheckBox system;EditText search;ImageView preview;Button save;
    static class App{final String pkg;final boolean system;App(String p,boolean s){pkg=p;system=s;}}
    interface Work{void run()throws Exception;}
    public void onCreate(Bundle state){super.onCreate(state);try{target=AdbCore.Endpoint.parse(getIntent().getStringExtra("target"));}catch(Exception e){finish();return;}
        LinearLayout root=vertical();root.setPadding(dp(16),dp(18),dp(16),dp(16));root.setBackgroundColor(MainActivity.BG);setContentView(root);
        root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(dp(16),dp(18)+insets.getSystemWindowInsetTop(),dp(16),dp(16)+insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
        root.addView(text("设备工具",22,true));root.addView(text("目标："+target.address(),13,true));
        TabHost tabs=new TabHost(this);tabs.setId(android.R.id.tabhost);LinearLayout structure=vertical();TabWidget strip=new TabWidget(this);strip.setId(android.R.id.tabs);FrameLayout content=new FrameLayout(this);content.setId(android.R.id.tabcontent);structure.addView(strip);structure.addView(content,new LinearLayout.LayoutParams(-1,0,1));tabs.addView(structure);root.addView(tabs,new LinearLayout.LayoutParams(-1,0,1));tabs.setup();
        LinearLayout application=vertical();application.setId(201);content.addView(application);tabs.addTab(tabs.newTabSpec("apps").setIndicator("设备应用").setContent(201));
        application.addView(text("当前用户的实际应用，按包名显示。",12,false));search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("搜索应用包名");application.addView(search);system=new CheckBox(this);system.setText("包含系统应用");buttons.add(system);application.addView(system);application.addView(button("刷新应用",()->run(this::refresh)));
        ScrollView list=new ScrollView(this);appRows=vertical();list.addView(appRows);application.addView(list,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});system.setOnCheckedChangeListener((v,checked)->{includeSystem=checked;run(this::refresh);});
        LinearLayout remote=vertical();remote.setGravity(Gravity.CENTER);remote.setId(202);content.addView(remote);tabs.addTab(tabs.newTabSpec("remote").setIndicator("遥控器").setContent(202));remote.addView(text("部分设备需额外允许模拟输入。",12,false));
        addKeyRow(remote,new int[]{0});addKeyRow(remote,new int[]{1,2,3});addKeyRow(remote,new int[]{4});addKeyRow(remote,new int[]{5,6});addKeyRow(remote,new int[]{7,8});
        LinearLayout screen=vertical();screen.setId(203);content.addView(screen);tabs.addTab(tabs.newTabSpec("screen").setIndicator("截图").setContent(203));screen.addView(text("受保护的画面可能显示为黑色。",12,false));screen.addView(button("截取画面",()->run(this::capture)));save=button("保存截图…",this::save);screen.addView(save);preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);screen.addView(preview,new LinearLayout.LayoutParams(-1,0,1));save.setEnabled(false);
        status=text("点击刷新读取应用，或切换遥控器、截图。",12,false);root.addView(status);root.addView(button("返回安装页面",()->{if(!busy)finish();}));
    }
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}LinearLayout vertical(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
    TextView text(String s,int size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(bold?MainActivity.INK:MainActivity.MUTED);v.setPadding(0,dp(5),0,dp(6));if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
    Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextSize(12);b.setOnClickListener(v->action.run());buttons.add(b);b.setEnabled(!busy);return b;}
    void addKeyRow(LinearLayout parent,int[] indices){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);for(int index:indices){String[] key=DeviceCommands.KEYS[index];row.addView(button(key[0],()->run(()->{shell(DeviceCommands.key(key[1]));note("按键已发送。若无响应，请检查模拟输入权限。",false);})),new LinearLayout.LayoutParams(dp(95),dp(56)));}parent.addView(row);}
    void ui(Runnable work){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())work.run();});}void note(String message,boolean failed){ui(()->{status.setText(message);status.setTextColor(failed?0xffb3261e:MainActivity.MUTED);});}
    void run(Work work){if(busy)return;busy=true;for(View b:buttons)b.setEnabled(false);getWindow().getDecorView().setKeepScreenOn(true);worker.submit(()->{try{if(keys==null)keys=AdbCore.Keys.load(new File(getFilesDir(),"adb-trust"));work.run();}catch(Exception e){note(AdbCore.friendly(e.getMessage()),true);}finally{ui(()->{busy=false;for(View b:buttons)b.setEnabled(true);save.setEnabled(screenshot!=null);getWindow().getDecorView().setKeepScreenOn(false);});}});}
    byte[] service(String name,int limit)throws Exception {AdbCore.Connection connection=new AdbCore.Connection(target,keys,message->note(message,false));active=connection;try{connection.timeout(30000);connection.open(name);return connection.readAll(limit);}finally{connection.close();active=null;}}
    String shell(String command)throws Exception{return DeviceCommands.checked(new String(service("shell:"+DeviceCommands.wrapped(command),4*1024*1024),StandardCharsets.UTF_8));}
    void refresh()throws Exception{final boolean all=includeSystem;note("正在读取设备应用…",false);Set<String> third=new HashSet<>(DeviceCommands.packages(shell("pm list packages -3 --user current")));List<String> every=all?DeviceCommands.packages(shell("pm list packages --user current")):new ArrayList<>(third);Collections.sort(every);List<App> value=new ArrayList<>();for(String pkg:every)value.add(new App(pkg,!third.contains(pkg)));ui(()->{apps.clear();apps.addAll(value);render();});note("已读取 "+value.size()+" 个应用 · 当前用户。",false);}
    void render(){if(appRows==null)return;for(int i=buttons.size()-1;i>=0;i--)if(buttons.get(i).getTag()!=null&&buttons.get(i).getTag().equals("app-action"))buttons.remove(i);appRows.removeAllViews();String filter=search.getText().toString().toLowerCase(Locale.ROOT);for(App app:apps){if(!app.pkg.toLowerCase(Locale.ROOT).contains(filter))continue;LinearLayout item=vertical();item.addView(text(app.pkg,14,true));item.addView(text(app.system?"系统应用":"用户应用",11,false));LinearLayout actions=new LinearLayout(this);addAction(actions,"打开",()->run(()->launch(app)));addAction(actions,"停止",()->run(()->action(app,"强制停止")));if(!app.system){addAction(actions,"清除数据",()->confirm(app,"清除数据"));addAction(actions,"卸载",()->confirm(app,"卸载"));}item.addView(actions);appRows.addView(item);}}
    void addAction(LinearLayout row,String name,Runnable action){Button b=button(name,action);b.setTag("app-action");row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}
    void launch(App app)throws Exception{String pkg=DeviceCommands.pkg(app.pkg);for(String category:new String[]{"LEANBACK_LAUNCHER","LAUNCHER"}){String component=DeviceCommands.component(shell("cmd package resolve-activity --brief --user current -a android.intent.action.MAIN -c android.intent.category."+category+" "+pkg));if(component!=null&&component.startsWith(pkg+"/")){shell("am start --user current -n '"+component+"'");note("应用已打开。",false);return;}}throw new IOException("此应用没有可打开的电视或手机桌面入口。");}
    void confirm(App app,String kind){if(busy)return;new AlertDialog.Builder(this).setTitle("确认"+kind).setMessage("目标："+target.address()+"\n应用："+app.pkg+"\n\n"+(kind.equals("卸载")?"卸载会删除应用及其数据。":"会删除登录状态、设置和本地数据，不只是清缓存。")).setNegativeButton("取消",null).setPositiveButton("确认",(d,w)->run(()->action(app,kind))).show();}
    void action(App app,String kind)throws Exception{if(app.system&&!kind.equals("强制停止"))throw new IOException("系统应用不提供卸载或清除数据。");String command=kind.equals("卸载")?"pm uninstall --user current ":kind.equals("清除数据")?"pm clear --user current ":"am force-stop --user current ";String output=shell(command+DeviceCommands.pkg(app.pkg));if(!kind.equals("强制停止")&&!output.equals("Success"))throw new IOException(output.isEmpty()?"设备未确认操作成功。":output);if(kind.equals("卸载"))ui(()->{apps.remove(app);render();});note(kind+"完成。",false);}
    void capture()throws Exception{note("正在截取画面…",false);byte[] data=service("exec:screencap -p",32*1024*1024);if(!DeviceCommands.validPng(data))throw new IOException("设备没有返回有效截图，可能不支持截屏。");BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("截图无法解码。");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(bounds.outWidth/options.inSampleSize>2000||bounds.outHeight/options.inSampleSize>2000){if(options.inSampleSize==0)options.inSampleSize=1;options.inSampleSize*=2;}Bitmap image=BitmapFactory.decodeByteArray(data,0,data.length,options);if(image==null)throw new IOException("截图无法解码。");ui(()->{preview.setImageBitmap(image);if(bitmap!=null)bitmap.recycle();bitmap=image;screenshot=data;});note("截图完成，可以保存到手机。",false);}
    void save(){if(busy||screenshot==null)return;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("image/png");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"设备截图.png");startActivityForResult(intent,301);}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=301||result!=RESULT_OK||data==null||data.getData()==null||screenshot==null)return;final byte[] bytes=screenshot;final android.net.Uri uri=data.getData();run(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法保存截图。");out.write(bytes);}note("截图已保存。",false);});}
    public void onBackPressed(){if(busy)note("操作正在进行，完成后可返回。",false);else super.onBackPressed();}
    protected void onDestroy(){super.onDestroy();AdbCore.Connection connection=active;if(connection!=null)connection.close();worker.shutdownNow();if(bitmap!=null)bitmap.recycle();}
}
